const getSecuredEnv = (key: string, fallback: string): string => {
    try {
        // @ts-ignore
        const val = process.env[key] || process.env[`NEXT_PUBLIC_${key}`];
        return (val && val !== "undefined") ? val : fallback;
    } catch (e) { return fallback; }
};

